//! The ribbon's Application tab, for the application rather than the project:
//! the Dark mode switch, the Brightness slider beneath it, and Settings, which
//! opens the settings window.

use gpui_kit::assets::IconName;
use gpui_kit::component::button::Button;
use gpui_kit::component::notification::Notification;
use gpui_kit::component::slider::{Slider, SliderEvent, SliderState};
use gpui_kit::component::switch::Switch;
use gpui_kit::component::{ActiveTheme as _, Icon, Sizable as _, Size, WindowExt as _, h_flex};
use gpui_kit::*;

use super::{Command, CommandPlace, CommandSize, Ribbon};
use crate::settings_window::OpenSettings;
use crate::{theme, theme_preference};

pub(super) const COMMANDS: &[CommandPlace] = &[
    CommandPlace {
        command: Command::DarkMode,
        group: "Appearance",
        size: CommandSize::Slim,
        primary: true,
    },
    // Beneath Dark mode, in the same column; not primary, so the collapsed
    // ribbon leaves it out.
    CommandPlace {
        command: Command::Brightness,
        group: "Appearance",
        size: CommandSize::Slim,
        primary: false,
    },
    CommandPlace {
        command: Command::Settings,
        group: "Preferences",
        size: CommandSize::Full,
        primary: true,
    },
];

/// Dark mode: a switch rather than a button, since it is on or off, taking the
/// room of a button of `size` but with no background, since it isn't one.
pub(super) fn dark_mode(size: CommandSize, cx: &mut Context<Ribbon>) -> AnyElement {
    let switch = Switch::new("dark-mode")
        .label("Dark mode")
        .checked(cx.theme().is_dark())
        .on_click(|dark, window, cx| set_dark_mode(*dark, window, cx));
    let block = h_flex().items_center().px_2();
    match size {
        CommandSize::Slim => block.h(super::SLIM_HEIGHT).w_full().child(switch.small()),
        CommandSize::Small => block
            .h(super::SMALL_HEIGHT)
            .flex_none()
            .child(switch.small()),
        // As tall as its switch and label need, as a full button is.
        CommandSize::Full => block.py_1().child(switch),
    }
    .into_any_element()
}

/// How wide the Brightness slider's track is.
const BRIGHTNESS_SLIDER_WIDTH: Pixels = px(120.);

/// How wide the Brightness setting's number is: room for any setting, so it
/// never changes the column's width as it changes.
const BRIGHTNESS_VALUE_WIDTH: Pixels = px(24.);

/// The Brightness slider's state, for the mode it was made for.
pub(super) struct BrightnessSlider {
    dark: bool,
    state: Entity<SliderState>,
    _subscription: Subscription,
}

#[cfg(test)]
impl BrightnessSlider {
    /// The mode the slider was made for, and where its thumb is.
    pub(super) fn shown(&self, cx: &App) -> (bool, f32) {
        (self.dark, self.state.read(cx).value().end())
    }
}

/// Makes the Brightness slider's state for the mode showing, or again when the
/// mode has changed since, so it shows that mode's own setting. Its track
/// runs the setting's full length, 0 at its middle; the thumb stops where the
/// mode's range does.
pub(super) fn sync_brightness(ribbon: &mut Ribbon, window: &mut Window, cx: &mut Context<Ribbon>) {
    let dark = cx.theme().is_dark();
    if ribbon
        .brightness
        .as_ref()
        .is_some_and(|slider| slider.dark == dark)
    {
        return;
    }
    let limit = theme::BRIGHTNESS_LIMIT as f32;
    let step = theme::brightness_of(dark, cx);
    let state = cx.new(|_| {
        SliderState::new()
            .min(-limit)
            .max(limit)
            .step(1.)
            .default_value(step as f32)
    });
    let subscription = cx.subscribe_in(
        &state,
        window,
        move |_, state, event: &SliderEvent, window, cx| {
            if let SliderEvent::Change(_) = event {
                // Straight away as it moves, kept to what the mode allows.
                // Where the thumb is now, rather than where the event says:
                // a double-click may have reset it since.
                let value = state.read(cx).value().end();
                let wanted = value.round() as i32;
                let taken = theme::set_brightness(dark, wanted, cx);
                if taken as f32 != value {
                    state.update(cx, |state, cx| state.set_value(taken as f32, window, cx));
                }
                cx.notify();
            } else {
                // Saved once let go.
                theme_preference::save_brightness(cx);
            }
        },
    );
    ribbon.brightness = Some(BrightnessSlider {
        dark,
        state,
        _subscription: subscription,
    });
}

/// Puts the mode showing back to its brightness at 0, and saves it.
pub(super) fn reset_brightness(ribbon: &mut Ribbon, window: &mut Window, cx: &mut Context<Ribbon>) {
    let dark = cx.theme().is_dark();
    theme::set_brightness(dark, 0, cx);
    if let Some(slider) = ribbon
        .brightness
        .as_ref()
        .filter(|slider| slider.dark == dark)
    {
        slider
            .state
            .update(cx, |state, cx| state.set_value(0., window, cx));
    }
    theme_preference::save_brightness(cx);
    cx.notify();
}

/// The setting as a signed number: "0" at the middle, "+2" above it, "-3"
/// below.
fn signed(step: i32) -> String {
    if step > 0 {
        format!("+{step}")
    } else {
        step.to_string()
    }
}

/// Brightness: a sun, the slider, and the setting, muted, with no background
/// of its own, as tall as a slim button. Double-clicking anywhere on it puts
/// it back to 0. Lets UI tests find it and its parts; inert in normal builds.
pub(super) fn brightness(
    ribbon: &Ribbon,
    size: CommandSize,
    cx: &mut Context<Ribbon>,
) -> AnyElement {
    let Some(slider) = ribbon.brightness.as_ref() else {
        return Empty.into_any_element();
    };
    let muted = cx.theme().muted_foreground;
    let step = theme::brightness(cx);
    let block = gpui_kit::TestSupportExt::test_support(h_flex().id("brightness"))
        .items_center()
        .gap_2()
        .px_2()
        .tooltip(|window, cx| {
            gpui_kit::component::tooltip::Tooltip::new(
                "Makes the whole interface lighter or darker, keeping its contrast. \
                 Double-click to reset it.",
            )
            .build(window, cx)
        })
        // Before the slider sees it, so the second click doesn't move it.
        .capture_any_mouse_down(cx.listener(|ribbon, event: &MouseDownEvent, window, cx| {
            if event.button == MouseButton::Left && event.click_count >= 2 {
                cx.stop_propagation();
                reset_brightness(ribbon, window, cx);
            }
        }))
        .child(Icon::new(IconName::Sun).with_size(Size::Small))
        .child(gpui_kit::TestSupportExt::test_support(
            div()
                .id("brightness-slider")
                .flex_none()
                .w(BRIGHTNESS_SLIDER_WIDTH)
                .child(Slider::new(&slider.state).horizontal()),
        ))
        .child(gpui_kit::TestSupportExt::test_support(
            div()
                .id("brightness-value")
                .flex_none()
                .w(BRIGHTNESS_VALUE_WIDTH)
                .text_sm()
                .text_right()
                .text_color(muted)
                .child(signed(step)),
        ));
    match size {
        CommandSize::Slim => block.h(super::SLIM_HEIGHT).w_full(),
        CommandSize::Small => block.h(super::SMALL_HEIGHT).flex_none(),
        CommandSize::Full => block.py_1(),
    }
    .into_any_element()
}

/// Settings: opens the settings in the inset panel.
pub(super) fn settings(
    button: impl Fn(&'static str, IconName, SharedString) -> Button,
) -> AnyElement {
    button("settings", IconName::Settings, "Settings".into())
        .tooltip_with_action(
            "Edit the system prompt each chat tab sends",
            &OpenSettings,
            None,
        )
        .on_click(|_, window, cx| window.dispatch_action(Box::new(OpenSettings), cx))
        .into_any_element()
}

/// Switches between light and dark mode, saving the choice.
pub fn set_dark_mode(dark: bool, window: &mut Window, cx: &mut App) {
    let mode = if dark {
        gpui_kit::component::ThemeMode::Dark
    } else {
        gpui_kit::component::ThemeMode::Light
    };
    if let Err(err) = theme_preference::set(mode, window, cx) {
        let note = Notification::error(format!("{err:#}")).title("Could not save dark mode");
        window.push_notification(note, cx);
    }
}
//! The user's light or dark mode choice, and each mode's brightness, saved in
//! the platform's per-user config directory so they carry across launches and
//! projects.

use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context as _, Result, anyhow};
use gpui_kit::component::{Theme, ThemeMode};
use gpui_kit::*;

/// Where the application keeps its per-user files, inside the config directory.
const APP_DIR: &str = "suspense";
const FILE_NAME: &str = "theme";

/// Applies the saved choice to the theme, or follows the system's appearance
/// if none has been made.
pub fn apply(window: &mut Window, cx: &mut App) {
    match file().ok().and_then(|file| load(&file)) {
        Some(mode) => Theme::change(mode, Some(window), cx),
        None => Theme::sync_system_appearance(Some(window), cx),
    }
}

/// Switches the theme to `mode` and saves it as the user's choice.
pub fn set(mode: ThemeMode, window: &mut Window, cx: &mut App) -> Result<()> {
    Theme::change(mode, Some(window), cx);
    save(mode, &file()?)
}

fn file() -> Result<PathBuf> {
    let config_dir = dirs::config_dir().ok_or_else(|| anyhow!("no config directory"))?;
    Ok(config_dir.join(APP_DIR).join(FILE_NAME))
}

/// Where each mode's brightness is kept, beside the light or dark mode choice.
const BRIGHTNESS_FILE_NAME: &str = "brightness";

/// Restores each mode's saved brightness, 0 for a mode never set. Call before
/// the theme's mode is applied, so the window opens at it.
pub fn restore_brightness(cx: &mut App) {
    let (dark, light) = brightness_file()
        .and_then(|file| load_brightness(&file))
        .unwrap_or_default();
    crate::theme::set_brightness(true, dark, cx);
    crate::theme::set_brightness(false, light, cx);
}

/// Saves both modes' brightness as they are now. It is only a convenience, so
/// failing to is ignored, and the setting still holds for the session.
pub fn save_brightness(cx: &App) {
    let (dark, light) = (
        crate::theme::brightness_of(true, cx),
        crate::theme::brightness_of(false, cx),
    );
    if let Some(file) = brightness_file() {
        save_brightness_to(dark, light, &file).ok();
    }
}

/// The brightness file; none in tests, which neither read nor write it.
fn brightness_file() -> Option<PathBuf> {
    let file = dirs::config_dir()?.join(APP_DIR).join(BRIGHTNESS_FILE_NAME);
    (!cfg!(test)).then_some(file)
}

/// Dark and light mode's brightness from `file`, a line for each mode, such
/// as `dark -2`; a mode missing or unreadable is at 0.
fn load_brightness(file: &Path) -> Option<(i32, i32)> {
    let text = fs::read_to_string(file).ok()?;
    let mut steps = (0, 0);
    for line in text.lines() {
        let mut words = line.split_whitespace();
        let (Some(mode), Some(step)) = (words.next(), words.next()) else {
            continue;
        };
        let Ok(step) = step.parse::<i32>() else {
            continue;
        };
        match mode {
            "dark" => steps.0 = step,
            "light" => steps.1 = step,
            _ => {}
        }
    }
    Some(steps)
}

fn save_brightness_to(dark: i32, light: i32, file: &Path) -> Result<()> {
    if let Some(dir) = file.parent() {
        fs::create_dir_all(dir).with_context(|| format!("could not create {}", dir.display()))?;
    }
    fs::write(file, format!("dark {dark}\nlight {light}\n"))
        .with_context(|| format!("could not save {}", file.display()))
}

fn load(file: &Path) -> Option<ThemeMode> {
    match fs::read_to_string(file).ok()?.trim() {
        "light" => Some(ThemeMode::Light),
        "dark" => Some(ThemeMode::Dark),
        _ => None,
    }
}

fn save(mode: ThemeMode, file: &Path) -> Result<()> {
    if let Some(dir) = file.parent() {
        fs::create_dir_all(dir).with_context(|| format!("could not create {}", dir.display()))?;
    }
    fs::write(file, mode.name()).with_context(|| format!("could not save {}", file.display()))
}

#[cfg(test)]
mod tests {
    use std::fs;
    use std::path::Path;

    use gpui_kit::component::ThemeMode;

    use super::{load, load_brightness, save, save_brightness_to};

    /// Each mode's brightness is saved on its own, and loads back as it was;
    /// never saved, both are at 0 once anything is; a mode missing is at 0.
    #[test]
    fn brightness_is_saved_per_mode_and_restored() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/brightness-preference-test");
        let file = dir.join("brightness");
        fs::remove_dir_all(&dir).ok();

        assert_eq!(load_brightness(&file), None);
        save_brightness_to(-3, 2, &file).unwrap();
        assert_eq!(load_brightness(&file), Some((-3, 2)));
        save_brightness_to(1, 0, &file).unwrap();
        assert_eq!(load_brightness(&file), Some((1, 0)));
        fs::write(&file, "light -4\n").unwrap();
        assert_eq!(load_brightness(&file), Some((0, -4)));
        fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn saved_choice_loads_back() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/theme-preference-test");
        let file = dir.join("theme");
        fs::remove_dir_all(&dir).ok();

        assert_eq!(load(&file), None);
        save(ThemeMode::Dark, &file).unwrap();
        assert_eq!(load(&file), Some(ThemeMode::Dark));
        save(ThemeMode::Light, &file).unwrap();
        assert_eq!(load(&file), Some(ThemeMode::Light));
    }
}

