/// mode keeps its own setting, the slider following the mode showing;
/// and double-clicking it puts it back to 0. At the brightest dark mode
/// allows, the ribbon's buttons still show lighter than its command area.
/// Not being primary, the collapsed ribbon leaves it out.
#[gpui_kit::test]
async fn the_brightness_slider_brightens_the_interface(cx: &mut TestAppContext) {
    use gpui_kit::component::{Theme, ThemeMode};
    use gpui_kit::{Bounds, Hsla, Pixels, point, px};

    use crate::ribbon::RibbonTab;
    use crate::theme;

    cx.update(|cx| {
        gpui_kit::init(cx);
        theme::init(cx);
        piton_syntax::init();
        ProjectDirectory::init(cx);
        super::bind_keys(cx);
        Theme::change(ThemeMode::Dark, None, cx);
    });
    let mut main = None;
    let window = cx.add_window(|window, cx| {
        let view = cx.new(|cx| MainWindow::new(window, cx));
        main = Some(view.clone());
        Root::new(view, window, cx)
    });
    let handle: gpui_kit::AnyWindowHandle = window.into();
    let ribbon = main.unwrap().read_with(cx, |main, _| main.ribbon.clone());
    ribbon.update(cx, |r, cx| r.select_tab(RibbonTab::Application, cx));
    cx.run_until_parked();

    // A solid, visible quad painted exactly at `bounds`, if any is.
    fn painted_at(window: &gpui_kit::Window, bounds: Bounds<Pixels>) -> Option<Hsla> {
        let scale = window.scale_factor();
        window
            .painted_quads()
            .into_iter()
            .find(|q| {
                (q.bounds.origin.x.0 - bounds.left().as_f32() * scale).abs() < 1.
                    && (q.bounds.origin.y.0 - bounds.top().as_f32() * scale).abs() < 1.
                    && (q.bounds.size.width.0 - bounds.size.width.as_f32() * scale).abs() < 1.
                    && (q.bounds.size.height.0 - bounds.size.height.as_f32() * scale).abs() < 1.
                    && q.background.as_solid().is_some_and(|c| c.a > 0.)
            })
            .and_then(|q| q.background.as_solid())
    }

    // Beneath Dark mode, in its column, with nothing behind it.
    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        let group = window.find("Appearance").bounds();
        let dark = window.find("dark-mode").bounds();
        let brightness = window.find("brightness").bounds();
        let slider = window.find("brightness-slider").bounds();
        assert_eq!(
            brightness.size.height,
            px(27.),
            "not a slim button's height"
        );
        assert_eq!(
            (brightness.left(), brightness.top() - group.top()),
            (group.left(), px(27.) + px(4.)),
            "it isn't stacked beneath Dark mode"
        );
        assert_eq!(dark.left() - group.left(), px(8.), "Dark mode moved");
        assert!(dark.bottom() <= brightness.top(), "it overlaps Dark mode");
        assert_eq!(
            brightness.right(),
            group.right(),
            "it isn't in Dark mode's column"
        );
        assert_eq!(slider.size.width, px(120.), "the track isn't 120px wide");
        assert!(
            painted_at(window, brightness).is_none(),
            "it has a background of its own"
        );
    })
    .unwrap();

    // Dragged all the way up, it stops where dark mode's range does,
    // brightening the greys but not the text.
    let (dark_low, dark_high) = {
        let range = theme::mode_brightness_range(true);
        (*range.start(), *range.end())
    };
    let drag = |cx: &mut TestAppContext, to_right: bool| {
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            let slider = window.find("brightness-slider").bounds();
            let end = if to_right {
                slider.right() + px(40.)
            } else {
                slider.left() - px(40.)
            };
            window.drag(slider.center(), point(end, slider.center().y), cx);
        })
        .unwrap();
        cx.run_until_parked();
    };
    drag(cx, true);
    cx.update(|cx| {
        assert_eq!(
            theme::brightness(cx),
            dark_high,
            "it didn't go as far as allowed"
        );
        assert_eq!(
            *theme::palette(cx),
            theme::brightened(&theme::DARK, dark_high)
        );
        assert_eq!(
            Theme::global(cx).foreground,
            theme::color(theme::DARK.text),
            "the text changed"
        );
    });
    assert_eq!(
        ribbon.read_with(cx, |r, cx| r.brightness_slider(cx)),
        Some((true, dark_high as f32)),
        "the thumb didn't stop at the end"
    );

    // At that brightness, the command area has moved, and a button on it
    // still shows lighter than it, as far as it did at 0.
    ribbon.update(cx, |r, cx| r.select_tab(RibbonTab::Project, cx));
    cx.run_until_parked();
    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        let area = painted_at(window, window.find("ribbon-controls").bounds())
            .expect("the command area isn't painted");
        let moved = theme::brightened(&theme::DARK, dark_high).ribbon;
        assert_eq!(area, theme::color(moved), "the command area didn't move");
        let button = painted_at(window, window.find("new-project").bounds())
            .expect("the button isn't painted");
        let shown: gpui_kit::Rgba = area.blend(button).into();
        let area_rgb: gpui_kit::Rgba = area.into();
        assert!(
            shown.r > area_rgb.r + 0.05,
            "the button {shown:?} isn't lighter than the command area {area_rgb:?}"
        );
        // Its base, moved as the base is.
        let base = (theme::brightened(&theme::DARK, dark_high).base & 0xff) as f32;
        assert!(
            (shown.r * 255. - base).abs() < 1.,
            "the button is {shown:?}, not the moved base"
        );
    })
    .unwrap();

    // Each mode keeps its own: light mode starts at 0, the slider with it,
    // and goes its own way; back in dark mode, dark's is as it was.
    ribbon.update(cx, |r, cx| r.select_tab(RibbonTab::Application, cx));
    drag(cx, false);
    cx.update(|cx| assert_eq!(theme::brightness(cx), dark_low));
    cx.update(|cx| Theme::change(ThemeMode::Light, None, cx));
    cx.run_until_parked();
    cx.update_window(handle, |_, window, cx| window.render_frame(cx))
        .unwrap();
    assert_eq!(
        ribbon.read_with(cx, |r, cx| r.brightness_slider(cx)),
        Some((false, 0.)),
        "the slider didn't show light mode's own"
    );
    cx.update(|cx| assert_eq!(*theme::palette(cx), theme::LIGHT));
    drag(cx, true);
    let light_high = *theme::mode_brightness_range(false).end();
    cx.update(|cx| {
        assert_eq!(theme::brightness(cx), light_high);
        assert_eq!(
            theme::brightness_of(true, cx),
            dark_low,
            "dark mode's moved"
        );
        Theme::change(ThemeMode::Dark, None, cx);
        assert_eq!(theme::brightness(cx), dark_low);
        assert_eq!(theme::brightness_of(false, cx), light_high);
    });
    cx.run_until_parked();
    cx.update_window(handle, |_, window, cx| window.render_frame(cx))
        .unwrap();
    assert_eq!(
        ribbon.read_with(cx, |r, cx| r.brightness_slider(cx)),
        Some((true, dark_low as f32))
    );

    // Double-clicking it puts it back to 0, the slider with it.
    cx.update_window(handle, |_, window, cx| {
        window.double_click("brightness-value", cx)
    })
    .unwrap();
    cx.run_until_parked();
    cx.update(|cx| {
        assert_eq!(theme::brightness(cx), 0, "a double-click didn't reset it");
        assert_eq!(*theme::palette(cx), theme::DARK);
        assert_eq!(
            theme::brightness_of(false, cx),
            light_high,
            "light mode's reset"
        );
    });
    assert_eq!(
        ribbon.read_with(cx, |r, cx| r.brightness_slider(cx)),
        Some((true, 0.))
    );
    // Double-clicking the track near its end resets it too, rather than
    // the second click moving it there.
    drag(cx, true);
    cx.update_window(handle, |_, window, cx| {
        use gpui_kit::{InputEvent as _, MouseButton, MouseDownEvent, MouseUpEvent};
        window.render_frame(cx);
        let slider = window.find("brightness-slider").bounds();
        let position = point(slider.right() - px(4.), slider.center().y);
        for click_count in [1, 2] {
            let down = MouseDownEvent {
                button: MouseButton::Left,
                position,
                modifiers: Default::default(),
                click_count,
                first_mouse: false,
            };
            window.dispatch_event(down.to_platform_input(), cx);
            let up = MouseUpEvent {
                button: MouseButton::Left,
                position,
                modifiers: Default::default(),
                click_count,
            };
            window.dispatch_event(up.to_platform_input(), cx);
            window.render_frame(cx);
        }
    })
    .unwrap();
    cx.run_until_parked();
    cx.update(|cx| assert_eq!(theme::brightness(cx), 0, "the second click moved it"));
    assert_eq!(
        ribbon.read_with(cx, |r, cx| r.brightness_slider(cx)),
        Some((true, 0.))
    );

    // Collapsed, Dark mode shows, being primary; Brightness doesn't.
    ribbon.update(cx, |r, cx| r.toggle_collapsed(cx));
    cx.run_until_parked();
    cx.update_window(handle, |_, window, cx| {
        window.render_frame(cx);
        assert!(window.try_find("dark-mode").is_some());
        assert!(
            window.try_find("brightness").is_none(),
            "the collapsed ribbon shows Brightness"
        );
    })
    .unwrap();
}

